import React, { useState } from "react";
import api from "../api/axios";
import { Link } from "react-router-dom";

function AddProduct() {
	const [formData, setFormData] = useState({
		product_name: "",
		product_url: "",
		product_brief_description: "",
		product_description: "",
		product_img: "",
		product_link: "",
		starting_price: "",
		price_range: "",
	});

	const [loading, setLoading] = useState(false);
	const [status, setStatus] = useState({ type: "", message: "" });

	const handleChange = (e) => {
		setFormData({
			...formData,
			[e.target.name]: e.target.value,
		});
	};

	const handleSubmit = async (e) => {
		e.preventDefault();
		setLoading(true);
		setStatus({ type: "", message: "" });

		try {
			const res = await api.post("/add-product", formData);
			setStatus({
				type: "success",
				message: `✅ Product "${formData.product_name}" added successfully! (ID: ${res.data.product_id || "OK"})`,
			});
			setFormData({
				product_name: "",
				product_url: "",
				product_brief_description: "",
				product_description: "",
				product_img: "",
				product_link: "",
				starting_price: "",
				price_range: "",
			});
		} catch (err) {
			console.error("Error inserting product:", err);
			setStatus({
				type: "danger",
				message:
					err.response?.data?.message ||
					"❌ Failed to insert product. Please check your backend connection.",
			});
		} finally {
			setLoading(false);
		}
	};

	return (
		<div className="container py-5 my-5" style={{ minHeight: "80vh" }}>
			<div className="row justify-content-center">
				<div className="col-12 col-md-8 col-lg-6">
					<div
						className="card shadow-lg p-4 p-md-5"
						style={{
							borderRadius: "24px",
							background: "rgba(255, 255, 255, 0.8)",
							backdropFilter: "blur(20px)",
							border: "1px solid rgba(255, 255, 255, 0.6)",
						}}
					>
						<h2 className="text-center mb-4 font-weight-bold" style={{ fontWeight: "700" }}>
							Add New Product
						</h2>

						{status.message && (
							<div className={`alert alert-${status.type} text-center`} role="alert">
								{status.message}
							</div>
						)}

						<form onSubmit={handleSubmit}>
							{/* Product Name */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Product Name</label>
								<input
									type="text"
									name="product_name"
									value={formData.product_name}
									onChange={handleChange}
									className="form-control"
									placeholder="e.g. iPhone 16 Pro"
									required
								/>
							</div>

							{/* Product URL / Slug */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Product URL / Slug</label>
								<input
									type="text"
									name="product_url"
									value={formData.product_url}
									onChange={handleChange}
									className="form-control"
									placeholder="e.g. iphone16pro"
									required
								/>
							</div>

							{/* Brief Description */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Brief Description</label>
								<input
									type="text"
									name="product_brief_description"
									value={formData.product_brief_description}
									onChange={handleChange}
									className="form-control"
									placeholder="Tagline / Brief summary"
									required
								/>
							</div>

							{/* Full Description */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Full Description</label>
								<textarea
									name="product_description"
									value={formData.product_description}
									onChange={handleChange}
									rows="3"
									className="form-control"
									placeholder="Comprehensive product specifications & description"
									required
								></textarea>
							</div>

							{/* Image URL */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Image URL</label>
								<input
									type="url"
									name="product_img"
									value={formData.product_img}
									onChange={handleChange}
									className="form-control"
									placeholder="https://.../image.jpg"
									required
								/>
							</div>

							{/* Product Link */}
							<div className="mb-3">
								<label className="form-label fw-semibold">Product Link</label>
								<input
									type="url"
									name="product_link"
									value={formData.product_link}
									onChange={handleChange}
									className="form-control"
									placeholder="https://www.apple.com/iphone"
									required
								/>
							</div>

							{/* Starting Price & Price Range */}
							<div className="row mb-4">
								<div className="col-6">
									<label className="form-label fw-semibold">Starting Price</label>
									<input
										type="text"
										name="starting_price"
										value={formData.starting_price}
										onChange={handleChange}
										className="form-control"
										placeholder="$999"
										required
									/>
								</div>
								<div className="col-6">
									<label className="form-label fw-semibold">Price Range</label>
									<input
										type="text"
										name="price_range"
										value={formData.price_range}
										onChange={handleChange}
										className="form-control"
										placeholder="From $41.62/mo."
										required
									/>
								</div>
							</div>

							{/* Submit Button */}
							<button
								type="submit"
								disabled={loading}
								className="btn btn-primary w-100 py-2 fw-semibold"
								style={{ borderRadius: "12px", background: "#0071e3", borderColor: "#0071e3" }}
							>
								{loading ? (
									<>
										<span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
										Submitting Product...
									</>
								) : (
									"Submit Product"
								)}
							</button>

							<div className="text-center mt-3">
								<Link to="/iphone" className="text-decoration-none" style={{ color: "#0071e3" }}>
									&larr; View all iPhones
								</Link>
							</div>
						</form>
					</div>
				</div>
			</div>
		</div>
	);
}

export default AddProduct;
